package vn.vrp;
import org.junit.jupiter.api.Test; import vn.vrp.algorithm.greedy.GreedyCvrpSolver; import vn.vrp.model.*; import vn.vrp.validator.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class GreedyCvrpSolverTest {
    @Test void createsValidTwoRouteSolution(){ProblemInstance p=fixture();Solution s=new GreedyCvrpSolver().solve(p);ValidationResult v=new SolutionValidator().validate(p,s);assertTrue(v.valid(),()->v.errors().toString());assertEquals(2,s.routes().size());assertEquals(100,s.totalDistance(),1e-9);assertEquals(List.of(1L,2L,3L),s.routes().getFirst().customers().stream().map(Customer::orderId).toList());}
    @Test void failsWhenFleetCannotCarryDemand(){ProblemInstance p=fixture();ProblemInstance impossible=new ProblemInstance(p.datasetId(),p.code(),p.type(),p.depot(),p.customers(),List.of(p.vehicles().getFirst()),p.arcs());assertThrows(IllegalStateException.class,()->new GreedyCvrpSolver().solve(impossible));}
    private ProblemInstance fixture(){Depot d=new Depot(1,1,"D0",28800,43200);List<Customer> cs=List.of(c(1,2,10,28800,32400),c(2,3,12,30000,34200),c(3,4,8,30600,36000),c(4,5,15,29400,33000),c(5,6,5,32400,36000));List<Vehicle> vs=List.of(v(1),v(2));double[][] xy={{0,0},{1,0},{2,0},{3,0},{0,1},{0,2}};Map<Long,Map<Long,TravelArc>> arcs=new HashMap<>();for(int i=0;i<6;i++)for(int j=0;j<6;j++)if(i!=j){double dist=(Math.abs(xy[i][0]-xy[j][0])+Math.abs(xy[i][1]-xy[j][1]))*10;arcs.computeIfAbsent((long)i+1,k->new HashMap<>()).put((long)j+1,new TravelArc(dist,(int)dist*120));}return new ProblemInstance(1,"DEMO","CVRP",d,cs,vs,arcs);}
    private Customer c(long id,long loc,double demand,int ready,int due){return new Customer(id,id,loc,"O"+id,demand,0,600,ready,due);}private Vehicle v(long id){return new Vehicle(id,"V"+id,"STANDARD",30,0,1,1,28800,43200,100,1,0);}
}
